INSERT INTO `hotel` VALUES (1,1,'吉隆坡希尔顿酒店','位于吉隆坡市中心，提供豪华住宿和一流设施，靠近主要景点和商业区。','3, Jalan Stesen Sentral, Kuala Lumpur Sentral, 50470 Kuala Lumpur, Wilayah Persekutuan Kuala Lumpur','846',4.6,'data:image/jpeg;base64,','2025-02-20 15:43:32','2025-02-20 15:43:32'),(2,1,'香格里拉大酒店','豪华五星级酒店，提供舒适的客房和卓越的服务，位于市中心，方便前往各主要景点。','11, Jln Sultan Ismail, Kuala Lumpur, 50250 Kuala Lumpur, Wilayah Persekutuan Kuala Lumpur','742',4.5,'data:image/jpeg;base64,','2025-02-20 15:43:32','2025-02-20 15:43:32'),(3,1,'吉隆坡文华东方酒店','提供奢华住宿体验，拥有壮观的城市景观和世界一流的设施，毗邻双子塔。','Kuala Lumpur City Centre, 50088 Kuala Lumpur, Federal Territory of Kuala Lumpur','1187',4.6,'data:image/jpeg;base64,','2025-02-20 15:43:32','2025-02-20 15:43:32'),(4,1,'吉隆坡双威普特拉酒店','提供豪华套房和卓越服务，设有世界一流的设施和餐饮选择，位于市中心。','100, Jalan Putra, Chow Kit, 50350 Kuala Lumpur, Wilayah Persekutuan Kuala Lumpur','544',4.5,'data:image/jpeg;base64,','2025-02-20 15:43:32','2025-02-20 15:43:32');
